/* Golden Braid AIDM B1 S21 Ochre Jelly — test cases
FILE: MonsterTestCase_Mentzer_Basic_Ochre_Jelly_Insert.sql
TARGET: PEQUOD / DnD (SQL Server 2016+)
SOURCE: Mentzer Basic 1983 DM Rulebook, Ochre Jelly, printed p.35.
B1 S21 selects species only. The Seeping Passage is a separate synthetic fixture.
2026-11-22. Idempotent INSERT-ONLY; source-checked and specified != deployed or tested.
*/
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57212,'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'OCHRE_JELLY-T001') THROW 57213,'OCHRE_JELLY-T001 missing: deploy scenario first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE ([ScenarioCode] NVARCHAR(MAX) NOT NULL,[TestCaseCode] NVARCHAR(MAX) NOT NULL,[SequenceNo] INT NOT NULL,[TestName] NVARCHAR(MAX) NOT NULL,[TestPhase] NVARCHAR(MAX) NOT NULL,[TestStatus] NVARCHAR(MAX) NOT NULL,[TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,[DiceFixtureJson] NVARCHAR(MAX) NULL,[AdditionalDataJson] NVARCHAR(MAX) NULL,[LinkedStoryRef] NVARCHAR(MAX) NULL,[AutomatedTestRef] NVARCHAR(MAX) NULL,[Notes] NVARCHAR(MAX) NULL);
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
 (N'OCHRE_JELLY-T001',N'JEL-C01',1,N'Ordinary Jelly attack: 2d6 exposed-flesh damage',N'COMBAT',N'Specified',1,N'Parent JEL-T001-1 has a legal attack under the normal shared combat turn; hit is resolved with validated d20.',N'Exactly one attack, using 5-HD hit row; a confirmed hit rolls 2d6 against exposed flesh; no extra effects or attacks.',N'{"attack_d20":18,"damage_2d6":[4,5]}',N'{"damage_if_hit":9,"attacks_per_round":1}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C02',2,N'Successful sword hit triggers 1d4+1 split',N'COMBAT',N'Specified',1,N'A legal normal sword attack hits generation-0 Jelly; split d4=2 and 2d8 child HP rolls are preselected.',N'The ordinary weapon does not reduce parent HP. Replace parent with exactly three 2-HD offspring with HP 8,10,6, each distinct actor. No bonus immediate actions.',N'{"attack_d20":19,"split_d4":2,"offspring_hp_2d8":[[4,4],[6,4],[2,4]]}',N'{"offspring_count":3,"offspring_hp":[8,10,6],"parent_removed":true,"weapon_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C03',3,N'Missed weapon attack cannot split',N'COMBAT',N'Specified',1,N'A normal sword attack misses the Jelly under the canonical hit procedure.',N'No split, no damage, no new combatants, original HP and roster unchanged.',N'{"attack_d20":1}',N'{"split":false,"offspring_count":0,"parent_hp":23}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C04',4,N'Successful lightning effect triggers splitting',N'COMBAT',N'Specified',1,N'Jelly is affected by a valid lightning attack under existing spell/effect resolution; this test fixes split d4=1.',N'Lightning causes 2 offspring (1d4+1), not electrical HP damage; resolve split as generic roster replacement without special combat phase.',N'{"split_d4":1}',N'{"offspring_count":2,"lightning_hp_damage":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C05',5,N'Torch fire can damage without splitting',N'COMBAT',N'Specified',1,N'A torch attack actually connects and the engine receives validated fire damage of 3 from the applicable canonical rule.',N'Apply exactly 3 fire damage to target HP and do not trigger splitting; do not invent new torch or hit mechanics.',N'{"validated_fire_damage":3}',N'{"parent_hp_before":23,"parent_hp_after":20,"split":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C06',6,N'Burning oil fire can damage without splitting',N'COMBAT',N'Specified',1,N'The Jelly is exposed to burning oil under an externally validated oil/fire rule producing 4 damage.',N'Apply the validated 4 fire damage; do not trigger weapon/lightning splitting or invent an oil damage rule.',N'{"validated_fire_damage":4}',N'{"parent_hp_before":23,"parent_hp_after":19,"split":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C07',7,N'Cold causes ordinary damage without splitting',N'COMBAT',N'Specified',1,N'A permitted cold effect deals validated 5 damage to the parent Jelly.',N'Reduce target HP by 5 normally; no offspring created.',N'{"validated_cold_damage":5}',N'{"parent_hp_before":23,"parent_hp_after":18,"split":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C08',8,N'Offspring are 2 HD and inflict half damage',N'COMBAT',N'Specified',1,N'The split generated 2-HD child JEL-T001-1A, which makes its lawful attack; its ordinary 2d6 result is 10.',N'Use 2-HD attack row for child, resolve one attack and deal half normal Jelly damage (5), no inherited parent 5-HD attack row.',N'{"attack_d20":19,"damage_2d6":[4,6]}',N'{"offspring_hit_dice":2,"damage":5,"normal_damage_before_halving":10}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C09',9,N'One-generation house-rule blocks re-splitting',N'COMBAT',N'Specified',1,N'A normal weapon hits a generation-1 offspring previously created by splitting.',N'No secondary offspring and no weapon HP damage, because only fire/cold harm Jelly and the approved house rule limits splitting to one generation.',N'{"attack_d20":19}',N'{"generation":1,"split":false,"weapon_hp_damage":0,"house_rule":"one generation only"}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C10',10,N'Split updates roster and normal turn continues',N'COMBAT',N'Specified',1,N'Generation-0 parent is successfully struck after its own/other actors action has been determined under shared combat timing.',N'Replace parent with children once; preserve ordinary initiative/action order and current-round eligibility; children do not gain bonus attacks or a fresh side initiative roll.',N'{"split_d4":2}',N'{"removed":["JEL-T001-1"],"created":["JEL-T001-1A","JEL-T001-1B","JEL-T001-1C"],"bonus_child_actions":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C11',11,N'Independent child HP; no artificial HP conservation',N'COMBAT',N'Specified',1,N'Successful split d4=2 creates three children with 2d8 rolls 4+4, 6+4, and 2+4.',N'Three independent 2-HD totals are 8,10,6 (24 combined); parent 23 HP is removed, not divided or conserved; offspring AC uses species rule.',N'{"split_d4":2,"offspring_hp_2d8":[[4,4],[6,4],[2,4]]}',N'{"offspring_hp":[8,10,6],"offspring_total_hp":24,"parent_original_hp":23,"children_count":3}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-C12',12,N'Generic dice/effects/roster change audit trace',N'COMBAT',N'Specified',1,N'A reproducible successful weapon-triggered split is interpreted by the Combat Agent.',N'Record the triggering hit, damage suppression, d4 split roll, child 2d8 rolls, source rule, one-generation overlay, removed parent, added children, and action continuity; narration cannot change results.',N'{"attack_d20":19,"split_d4":2,"offspring_hp_2d8":[[4,4],[6,4],[2,4]]}',N'{"trace_required":["weapon_hit","no_weapon_damage","split_d4","offspring_2d8","generation_limit","roster_delta","no_bonus_actions"],"jelly_specific_algorithm":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat-engine acceptance case only; not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E01',13,N'Generate one parent and physical scene',N'ENCOUNTER',N'Specified',1,N'The S21 synthetic Seeping Passage fixture is selected before any encounter choices.',N'Generate exactly one 5-HD 23-HP Jelly and a damp stone gallery with cracked masonry; do not use B1 stocked HP or require a combat event.',NULL,N'{"species":"OCHRE_JELLY","count":1,"starting_hp":23}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E02',14,N'Describe observable mass without revealing hidden knowledge',N'ENCOUNTER',N'Specified',1,N'Party encounters a yellow-brown mass near cracked masonry; character knowledge/visibility not yet established.',N'Narrate only sensory facts available to the party; do not automatically label it an Ochre Jelly, reveal immunity/splitting rules, or infer room geometry from art.',NULL,N'{"automatic_identification":false,"hidden_rules_revealed":false}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E03',15,N'Normal surprise belongs to Encounter, not Combat',N'ENCOUNTER',N'Specified',1,N'A valid meeting occurs; independent example party surprise=5 and Jelly surprise=4.',N'Resolve one d6 per side under normal surprise rules; neither surprised in this branch. No automatic surprise granted by seepage/appearance; pass only verified surprise facts to Combat.',N'{"party_surprise_d6":5,"jelly_surprise_d6":4}',N'{"party_surprised":false,"jelly_surprised":false,"one_roll_per_side":true}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E04',16,N'Interpret investigation or cautious movement',N'ENCOUNTER',N'Specified',1,N'Party chooses to examine, probe, approach with torch or skirt the visible mass.',N'DM/Encounter interprets intentions, sight, contact and actual scene constraints without forcing a Jelly attack, identification or early Combat roll.',NULL,N'{"options":["examine","probe","approach with torch","pass around"],"forced_combat":false}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E05',17,N'Avoidance and withdrawal remain possible',N'ENCOUNTER',N'Specified',1,N'Party elects to withdraw or pass around the mass when scene circumstances may permit.',N'Do not force combat; assess movement/contact and valid passage conditions dynamically; neither the species table nor artwork scripts a trap or mandatory damage.',NULL,N'{"avoidance_possible":true,"automatic_attack":false}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.'),
 (N'OCHRE_JELLY-T001',N'JEL-E06',18,N'Combat receives only a validated structured handoff',N'ENCOUNTER',N'Specified',1,N'The Encounter Engine has established actual hostility/contact and a fight begins.',N'Supply one 23-HP parent Jelly, AC8, 5 HD, one attack 2d6, movements 30/10, positions only if known, supported effects and confirmed surprise; no investigation or narrative branching is executed by Combat.',NULL,N'{"monster_count":1,"starting_hp":23,"armor_class":8,"hit_dice":"5*","encounter_logic_in_combat":false}',NULL,NULL,N'Future Encounter Engine (not built); specification only, not executed.');
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestCase] AS t WITH(UPDLOCK,HOLDLOCK) WHERE t.[ScenarioCode]=s.[ScenarioCode] AND t.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted Ochre Jelly test definitions: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [TestCount] FROM [Test].[MonsterTestCase]
WHERE [ScenarioCode]=N'OCHRE_JELLY-T001' GROUP BY [ScenarioCode],[TestPhase],[TestStatus] ORDER BY [TestPhase],[TestStatus];
